// Three-player protocol test: tag mode logic, three-way relay, leave handling.
const WebSocket = require('/home/lane/rblx/node_modules/ws');
const BASE = 'http://localhost:3001';

let pass = 0, fail = 0;
const ok = (name, cond) => { cond ? pass++ : fail++; console.log(`  ${cond ? '✓' : '✗ FAIL'} ${name}`); };

async function call(path, opts = {}, cookie = '') {
  const res = await fetch(BASE + '/api' + path, {
    method: opts.method || (opts.body ? 'POST' : 'GET'),
    headers: { 'Content-Type': 'application/json', Cookie: cookie },
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  return { status: res.status, data: await res.json().catch(() => ({})), cookie: (res.headers.get('set-cookie') || '').split(';')[0] };
}

function wsConnect(cookie) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket('ws://localhost:3001/ws', { headers: { Cookie: cookie } });
    ws.inbox = [];
    ws.waiters = [];
    ws.on('message', (raw) => {
      const msg = JSON.parse(raw);
      const w = ws.waiters.find((x) => x.match(msg));
      if (w) { ws.waiters.splice(ws.waiters.indexOf(w), 1); w.resolve(msg); }
      else { ws.inbox.push(msg); if (ws.inbox.length > 300) ws.inbox.shift(); }
    });
    ws.on('open', () => resolve(ws));
    ws.on('error', reject);
  });
}

// wait for a message matching predicate (checks backlog first)
function expect(ws, pred, timeout = 6000, label = '') {
  const match = typeof pred === 'string' ? (m) => m.t === pred : pred;
  const found = ws.inbox.find(match);
  if (found) { ws.inbox.splice(ws.inbox.indexOf(found), 1); return Promise.resolve(found); }
  return new Promise((resolve, reject) => {
    ws.waiters.push({ match, resolve });
    setTimeout(() => reject(new Error('timeout: ' + (label || pred))), timeout);
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const sfx = Math.random().toString(36).slice(2, 6);
  const names = ['p1_' + sfx, 'p2_' + sfx, 'p3_' + sfx];
  const cookies = [];
  for (const n of names) {
    const r = await call('/register', { body: { username: n, password: 'test1234' } });
    cookies.push(r.cookie);
  }
  const games = (await call('/games', {}, cookies[0])).data.games;
  const tagGame = games.find((g) => g.name === 'Zap Tag');

  console.log('— three players join Zap Tag —');
  const ws = [];
  const joined = [];
  for (let i = 0; i < 3; i++) {
    ws[i] = await wsConnect(cookies[i]);
    ws[i].send(JSON.stringify({ t: 'join', gameId: tagGame.id }));
    joined[i] = await expect(ws[i], 'joined');
  }
  ok('all three in same instance', joined[0].instanceId === joined[1].instanceId && joined[1].instanceId === joined[2].instanceId);
  ok('p3 snapshot lists 2 other players', joined[2].players.length === 2);

  // everyone should have an lb with 3 entries and an "it" assigned
  const lb3 = await expect(ws[0], (m) => m.t === 'lb' && m.entries.length === 3, 6000, 'lb with 3 entries');
  ok('leaderboard reaches 3 entries', lb3.entries.length === 3);
  const itId = lb3.itId;
  ok('server assigned an "it" with ≥2 players', !!itId);

  console.log('— three-way relay —');
  // p1 moves; p2 AND p3 both see it
  ws[0].send(JSON.stringify({ t: 'move', p: [5, 2, 5], yaw: 1, anim: 'walk' }));
  const m2 = await expect(ws[1], (m) => m.t === 'p' && m.p[0] === 5, 4000, 'p relay to p2');
  const m3 = await expect(ws[2], (m) => m.t === 'p' && m.p[0] === 5, 4000, 'p relay to p3');
  ok('movement relayed to both peers', m2.anim === 'walk' && m3.anim === 'walk');

  ws[1].send(JSON.stringify({ t: 'chat', text: 'three player party' }));
  const c1 = await expect(ws[0], (m) => m.t === 'chat' && m.text === 'three player party', 4000, 'chat to p1');
  const c3 = await expect(ws[2], (m) => m.t === 'chat' && m.text === 'three player party', 4000, 'chat to p3');
  ok('chat reaches both peers', c1.username === names[1] && c3.username === names[1]);

  console.log('— tag mechanics —');
  // it player and one victim stand together; third stands far away
  const itIdx = joined.findIndex((j, i) => {
    const id = lb3.entries.find((e) => e.it)?.id;
    return j.selfId === id;
  });
  const victimIdx = (itIdx + 1) % 3;
  const bystanderIdx = (itIdx + 2) % 3;
  // wait out the tagback cooldown, then collide
  await sleep(2200);
  ws[itIdx].send(JSON.stringify({ t: 'move', p: [10, 2, 10], yaw: 0, anim: 'idle' }));
  ws[victimIdx].send(JSON.stringify({ t: 'move', p: [10.5, 2, 10], yaw: 0, anim: 'idle' }));
  ws[bystanderIdx].send(JSON.stringify({ t: 'move', p: [-20, 2, -20], yaw: 0, anim: 'idle' }));
  const tag = await expect(ws[bystanderIdx], 'tag', 6000, 'tag transfer');
  ok('zap transferred to the touched player', tag.itId === joined[victimIdx].selfId);
  ok('tagger credited with the zap', tag.by === joined[itIdx].selfId);
  const lbAfterTag = await expect(ws[bystanderIdx], (m) => m.t === 'lb' && m.entries.some((e) => e.score > 0), 4000, 'lb after tag');
  ok('scoreboard shows tagger score 1', lbAfterTag.entries.find((e) => e.id === joined[itIdx].selfId).score === 1);
  // bystander far away must NOT get tagged during cooldown window
  await sleep(2400);
  const stray = ws[bystanderIdx].inbox.find((m) => m.t === 'tag' && m.itId === joined[bystanderIdx].selfId);
  ok('distant player never tagged', !stray);

  console.log('— leave updates everyone —');
  ws[2].close();
  await expect(ws[0], (m) => m.t === 'pleave' && m.id === joined[2].selfId, 5000, 'pleave');
  const lbAfterLeave = await expect(ws[0], (m) => m.t === 'lb' && m.entries.length === 2, 5000, 'lb after leave');
  ok('scoreboard drops to 2 after leave (fix verified)', lbAfterLeave.entries.length === 2);

  console.log('— collect mode with 2 players —');
  const collect = games.find((g) => g.name === 'Glimmer Rush');
  ws[0].send(JSON.stringify({ t: 'join', gameId: collect.id }));
  ws[1].send(JSON.stringify({ t: 'join', gameId: collect.id }));
  const j0 = await expect(ws[0], 'joined');
  await expect(ws[1], 'joined');
  const coins = j0.world.parts.filter((p) => p.type === 'coin');
  // p1 grabs two coins
  for (const coin of coins.slice(0, 2)) {
    ws[0].send(JSON.stringify({ t: 'move', p: [coin.x, coin.y, coin.z], yaw: 0, anim: 'idle' }));
    await sleep(80);
    ws[0].send(JSON.stringify({ t: 'touch', partId: coin.id }));
    await expect(ws[1], (m) => m.t === 'coin' && m.partId === coin.id, 4000, 'coin broadcast');
  }
  const lbCoins = await expect(ws[1], (m) => m.t === 'lb' && m.entries.some((e) => e.score === 2), 4000, 'coin lb');
  ok('coin score reaches 2 on peer scoreboard', !!lbCoins);
  // double-grab same coin rejected (still hidden)
  ws[1].send(JSON.stringify({ t: 'move', p: [coins[0].x, coins[0].y, coins[0].z], yaw: 0, anim: 'idle' }));
  await sleep(80);
  ws[1].send(JSON.stringify({ t: 'touch', partId: coins[0].id }));
  let regrab = false;
  try { await expect(ws[0], (m) => m.t === 'coin' && m.partId === coins[0].id && m.by !== j0.selfId, 900, 'regrab'); regrab = true; } catch (e) {}
  ok('taken coin cannot be re-grabbed before respawn', !regrab);

  ws[0].close(); ws[1].close();
  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})().catch((e) => { console.error('TEST CRASH:', e.message); process.exit(1); });
